css:
/* Fonts — add .woff2 files to Anki media folder (prefix _ prevents cleanup) */
@font-face { font-family: 'Inter'; src: url('_inter.woff2') format('woff2'); font-weight: 100 900; }
@font-face { font-family: 'JetBrains Mono'; src: url('_jetbrains-mono.woff2') format('woff2'); font-weight: 400 500; }
@font-face { font-family: 'Noto Serif JP'; src: url('_noto-serif-jp.woff2') format('woff2'); font-weight: 400 700; }
@font-face { font-family: 'YuKyokasho'; src: url('_yukyokasho-bold.woff2') format('woff2'); font-weight: 600 900; }
@font-face { font-family: 'PitchNum'; src: url('_pitch_num.woff2') format('woff2'); font-weight: 100 900; }

:root,
:root[class*=night-mode] {
    /* ═══════════════════════════════════════════════════════
       ⚙  SETTINGS — Change these to customize your cards.
       ═══════════════════════════════════════════════════════ */

    /* Layout */
    --tategaki: off;               /* on | off                            */
    --color-scheme: black;          /* blue | black | red | purple | white */
    --audio-labels: on;            /* on | off                            */
    --card-transparency: on;       /* on | off                            */
    --toggle-align: center;        /* left | center                       */
    --debug: off;                  /* on | off                            */
    --stability-mode: off;         /* on | off                            */

    /* Word */
    --word-text: back only;        /* front & back | back only | off      */
    --word-audio: front & back;    /* front & back | back only | off      */
    --word-audio-buttons: fallback;  /* front only | back only | front & back | fallback | none */
    --word-autoplay: front only;   /* front only | back only | front & back | when no def audio | none */
    --word-text-play: on;          /* on | off                            */
    --word-furigana: back only;    /* front & back | back only | off      */
    --word-pitch-color: back only; /* front & back | back only | off      */
    --pitch-graph: on;             /* on | off                            */

    /* German */
    --gender-colors: on;           /* on | off                            */
    --grammar-info: back only;     /* front & back | back only | off      */

    /* Sentence */
    --sentence-text: back only;    /* front & back | back only | off      */
    --sentence-audio: front & back;/* front & back | back only | off      */
    --sentence-audio-buttons: fallback;/* front only | back only | front & back | fallback | none */
    --sentence-autoplay: front & back;/* front only | back only | front & back | when no def audio | none */
    --sentence-text-play: on;      /* on | off                            */
    --sentence-furigana: back only;/* front & back | back only | off      */
    --sentence-pitch-color: off;   /* front & back | back only | off      */

    /* Image */
    --image: back only;            /* front & back | back only | off      */

    /* Definitions */
    --definition-text-mono: on when unlocked, otherwise toggle;/* on | off | on when unlocked, otherwise off | on when unlocked, otherwise toggle */
    --definition-text-bi: on when mono locked, otherwise toggle;/* on | off | on when mono locked, otherwise off | on when mono locked, otherwise toggle */
    --definition-audio-buttons: fallback;/* on | fallback | off                 */
    --definition-autoplay-mono: on when unlocked or on reveal;/* on | on when unlocked, otherwise off | on when unlocked or on reveal | off */
    --definition-autoplay-bi: on when mono locked or on reveal;/* on | on when mono locked, otherwise off | on when mono locked or on reveal | off */
    --definition-text-play: on;    /* on | off                            */
    --definition-default: bilingual; /* monolingual | bilingual             */
    --definition-furigana: on;     /* on | off                            */
    --definition-pitch-color: on;  /* on | off                            */
    --definition-align: left;      /* left | center                       */

    /* Notes */
    --notes-text: on;              /* on | off                            */
    --notes-align: left;           /* left | center                       */

    /* Details Toggle */
    --details-word-text: off;      /* on | off                            */
    --details-word-audio: off;     /* on | off                            */
    --details-word-autoplay: off;  /* on | off                            */
    --details-pitch-graph: off;    /* on | off                            */
    --details-sentence-text: off;  /* on | off                            */
    --details-sentence-audio: off; /* on | off                            */
    --details-sentence-autoplay: off;/* on | off                          */
    --details-image: off;          /* on | off                            */
    --details-definition-text-mono: off;/* on | off                       */
    --details-definition-text-bi: off;/* on | off                         */
    --details-definition-audio: off;/* on | off                           */
    --details-notes-text: on;      /* on | off                            */

    /* Hotkeys */
    --hotkey-word-audio: z;        /* keyboard key                        */
    --hotkey-sentence-audio: x;    /* keyboard key                        */
    --hotkey-definition-audio: c;  /* keyboard key (back only)            */
    --hotkey-play-all: ,;          /* keyboard key                        */
    --hotkey-stop-all: .;          /* keyboard key                        */
    --hotkey-def-toggle: h;        /* keyboard key (back only)            */
    --hotkey-details-toggle: n;    /* keyboard key (back only)            */

    /* ═══════════════════════════════════════════════════════
       ⚙  MODES — Tag & deck-based settings overrides.
       A mode triggers if the card's tags contain --mode-N-tag
       OR the card's deck starts with --mode-N-deck (prefix
       match: "Mining" matches "Mining::Vocab::N2").
       Only list settings you want to override (rest inherit
       from defaults above). Lower modes beat higher modes,
       and tag matches unconditionally beat deck matches.
       ═══════════════════════════════════════════════════════ */
    /* —— Mode 1: Raw Listening ————————————————————————————————— */
    --mode-1-name: Raw Listening;
    --mode-1-tag: _mvj::raw-listening;
    --mode-1-deck: ;
    --mode-1-toggle-align: center;
    --mode-1-word-text: off;
    --mode-1-word-audio-buttons: front & back;
    --mode-1-sentence-autoplay: front only;
    --mode-1-sentence-text: off;
    --mode-1-notes-text: off;

    /* —— Mode 2: Word Audio Only ——————————————————————————————— */
    --mode-2-name: Word Audio Only;
    --mode-2-tag: _de::word;
    --mode-2-deck: ;
    --mode-2-sentence-audio: back only;

    /* —— Mode 3: Sentence Audio Only ——————————————————————————— */
    --mode-3-name: Sentence Audio Only;
    --mode-3-tag: _de::sentence;
    --mode-3-deck: ;
    --mode-3-word-audio: back only;

    /* —— Mode 4: Image ————————————————————————————————————————— */
    --mode-4-name: Image;
    --mode-4-tag: _de::image;
    --mode-4-deck: ;
    --mode-4-word-audio: back only;
    --mode-4-sentence-audio: back only;
    --mode-4-image: front & back;

    /* —— Mode 5: Reading ——————————————————————————————————————— */
    --mode-5-name: Reading;
    --mode-5-tag: _de::reading;
    --mode-5-deck: ;
    --mode-5-tategaki: on;
    --mode-5-word-audio: back only;
    --mode-5-sentence-text: front & back;
    --mode-5-sentence-audio: back only;

    /* —— Mode 6: Vocab ————————————————————————————————————————— */
    --mode-6-name: Vocab;
    --mode-6-tag: _de::vocab;
    --mode-6-deck: ;
    --mode-6-word-text: front & back;
    --mode-6-word-audio: back only;
    --mode-6-sentence-audio: back only;

    /* —— Mode 7: Furigana —————————————————————————————————————— */
    --mode-7-name: Furigana;
    --mode-7-tag: jp_::furigana;
    --mode-7-deck: ;
    --mode-7-word-furigana: front & back;
    --mode-7-sentence-furigana: front & back;

    /* ═══════════════════════════════════════════════════════ */

    /* Override Anki's --canvas so the Qt toolbar matches */
    --canvas: #0c0d12;

    /* Surface palette — blue-tinted darks for depth */
    --bg: #0c0d12;
    --bg-card: #15161c;
    --bg-surface: #1e1f27;
    --bg-surface-hover: #26272f;
    --bg-overlay: rgba(12, 13, 18, 0.96);

    /* Borders */
    --border: rgba(255, 255, 255, 0.06);
    --border-light: rgba(255, 255, 255, 0.09);

    /* Text — 4-level hierarchy */
    --text-1: rgba(255, 255, 255, 0.92);
    --text-2: rgba(255, 255, 255, 0.56);
    --text-3: rgba(255, 255, 255, 0.30);

    /* Accent — muted indigo */
    --accent: #6b7ea8;
    --accent-text: #8d9bbe;
    --accent-soft: rgba(107, 126, 168, 0.10);
    --accent-glow: rgba(107, 126, 168, 0.18);
    --accent-soft-bright: rgba(107, 126, 168, 0.20);
    --flash-border: rgba(255, 255, 255, 0.10);
    --flash-bg: rgba(255, 255, 255, 0.04);

    /* Card surface */
    --card-bg: rgba(21, 22, 28, 0.58);
    --card-bg-solid: rgb(21, 22, 28);
    --card-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.06),
        0 1px 3px rgba(8, 10, 24, 0.40),
        0 4px 12px rgba(8, 10, 24, 0.28),
        0 16px 36px rgba(8, 10, 24, 0.16);

    /* UI element colors */
    --shimmer-color: rgba(255, 255, 255, 0.04);
    --replay-stroke: rgba(255, 255, 255, 0.07);
    --graph-color: #8a8a8a;
    --image-shadow:
        inset 0 0 0 1px rgba(255, 255, 255, 0.06),
        inset 0 2px 8px rgba(0, 0, 0, 0.25);
    --toggle-bg: rgba(255, 255, 255, 0.02);
    --toggle-border: rgba(255, 255, 255, 0.05);
    --toggle-hover-bg: rgba(255, 255, 255, 0.04);
    --toggle-hover-border: rgba(255, 255, 255, 0.10);
    --divider-color: rgba(255, 255, 255, 0.50);
    --answer-divider-color: transparent;

    /* Pitch accent colors */
    --pitch-atamadaka: #d94040;
    --pitch-heiban: #3350e8;
    --pitch-nakadaka: #e89b33;
    --pitch-kifuku: #9b40d9;
    --pitch-odaka: #2db852;
    --pitch-keihan-heiban: #3bb2ed;
    --pitch-keihan-low-heiban: #096999;
    --pitch-keihan-atamadaka: #f76d94;
    --pitch-keihan-nakadaka: #a89c0f;
    --pitch-keihan-low-nakadaka: #876333;
    --pitch-keihan-odaka: #658065;
    --pitch-black: var(--text-1);

    /* Fonts */
    --mono: 'JetBrains Mono', monospace;
    --sans: 'Inter', -apple-system, system-ui, sans-serif;
    --jp: 'Noto Serif JP', 'Hiragino Mincho ProN', 'Yu Mincho', serif;
    --jp-kyokasho: 'YuKyokasho', 'YuKyokashotai', 'UD Digi Kyokasho NP-R', var(--jp);

    /* Motion */
    --ease: cubic-bezier(0.16, 1, 0.3, 1);
    --spring: cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* — Color scheme overrides —
   The blue theme's values live in :root above (they double as fallback
   defaults). Every other theme is a single block below.

   To add a new theme, copy this template and fill in your values:

   :root[data-color-scheme="my-theme"] {
       -- Surface palette --
       --canvas:             #...;
       --bg:                 #...;
       --bg-card:            #...;
       --bg-surface:         #...;
       --bg-surface-hover:   #...;
       --bg-overlay:         rgba(..., 0.96);
       --border:             rgba(...);          (dark default: white 0.06)
       --border-light:       rgba(...);          (dark default: white 0.09)
       -- Text --
       --text-1:             rgba(...);
       --text-2:             rgba(...);
       --text-3:             rgba(...);
       -- Accent --
       --accent:             #...;
       --accent-text:        #...;
       --accent-soft:        rgba(..., 0.12);
       --accent-glow:        rgba(..., 0.22);
       --accent-soft-bright: rgba(..., 0.20);    (text-play breathe midpoint)
       --flash-border:       rgba(...);          (dark default: white 0.10)
       --flash-bg:           rgba(...);          (dark default: white 0.04)
       -- Card surface --
       --card-bg:            rgba(..., 0.58);    (transparent card bg)
       --card-bg-solid:      rgb(...);           (opaque — used when transparency is off)
       --card-shadow:        ...;                (4-layer box-shadow)
       -- UI elements (only override for light themes) --
       --shimmer-color:      rgba(...);          (dark default: white 0.04)
       --replay-stroke:      rgba(...);          (dark default: white 0.07)
       --graph-color:        #...;               (dark default: #8a8a8a)
       --image-shadow:       ...;                (2-layer inset box-shadow)
       --toggle-bg:          rgba(...);          (dark default: white 0.02)
       --toggle-border:      rgba(...);          (dark default: white 0.05)
       --toggle-hover-bg:    rgba(...);          (dark default: white 0.04)
       --toggle-hover-border:rgba(...);          (dark default: white 0.10)
       --divider-color:      rgba(...);          (dark default: white 0.50)
       --answer-divider-color:rgba(...);         (dark default: transparent)
       -- Pitch accent (only override if colors need adjustment) --
       --pitch-atamadaka:    #...;               (default: #d94040)
       --pitch-heiban:       #...;               (default: #3350e8)
       --pitch-nakadaka:     #...;               (default: #e89b33)
       --pitch-kifuku:       #...;               (default: #9b40d9)
       --pitch-odaka:        #...;               (default: #2db852)
       --pitch-keihan-heiban:#...;               (default: #3bb2ed)
       --pitch-keihan-low-heiban:#...;           (default: #096999)
       --pitch-keihan-atamadaka:#...;            (default: #f76d94)
       --pitch-keihan-nakadaka:#...;             (default: #a89c0f)
       --pitch-keihan-low-nakadaka:#...;         (default: #876333)
       --pitch-keihan-odaka: #...;               (default: #658065)
   }

   Dark themes only need: surface palette + accent + card surface (3 vars).
   Light themes should also override the UI element group (10 vars).
   Pitch accent colors rarely need overriding — only if contrast is poor.
   Any variable you omit inherits the blue/dark default from :root.
*/

:root[data-color-scheme="black"] {
    --canvas: #0a0a0a;
    --bg: #0a0a0a;
    --bg-card: #141414;
    --bg-surface: #1c1c1c;
    --bg-surface-hover: #242424;
    --bg-overlay: rgba(10, 10, 10, 0.96);
    --accent: #909090;
    --accent-text: #a8a8a8;
    --accent-soft: rgba(144, 144, 144, 0.10);
    --accent-glow: rgba(144, 144, 144, 0.18);
    --accent-soft-bright: rgba(144, 144, 144, 0.20);
    --card-bg: rgba(20, 20, 20, 0.58);
    --card-bg-solid: rgb(20, 20, 20);
    --card-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.06),
        0 1px 3px rgba(0, 0, 0, 0.40),
        0 4px 12px rgba(0, 0, 0, 0.28),
        0 16px 36px rgba(0, 0, 0, 0.16);
}

:root[data-color-scheme="red"] {
    --canvas: #100808;
    --bg: #100808;
    --bg-card: #1a1010;
    --bg-surface: #231818;
    --bg-surface-hover: #2b1f1f;
    --bg-overlay: rgba(16, 8, 8, 0.96);
    --accent: #a87070;
    --accent-text: #c09090;
    --accent-soft: rgba(168, 112, 112, 0.10);
    --accent-glow: rgba(168, 112, 112, 0.18);
    --accent-soft-bright: rgba(168, 112, 112, 0.20);
    --card-bg: rgba(26, 16, 16, 0.58);
    --card-bg-solid: rgb(26, 16, 16);
    --card-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.06),
        0 1px 3px rgba(16, 4, 4, 0.40),
        0 4px 12px rgba(16, 4, 4, 0.28),
        0 16px 36px rgba(16, 4, 4, 0.16);
}

:root[data-color-scheme="purple"] {
    --canvas: #0e0a14;
    --bg: #0e0a14;
    --bg-card: #171320;
    --bg-surface: #201b2a;
    --bg-surface-hover: #282332;
    --bg-overlay: rgba(14, 10, 20, 0.96);
    --accent: #8878b0;
    --accent-text: #a898c8;
    --accent-soft: rgba(136, 120, 176, 0.10);
    --accent-glow: rgba(136, 120, 176, 0.18);
    --accent-soft-bright: rgba(136, 120, 176, 0.20);
    --card-bg: rgba(23, 19, 32, 0.58);
    --card-bg-solid: rgb(23, 19, 32);
    --card-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.06),
        0 1px 3px rgba(10, 6, 16, 0.40),
        0 4px 12px rgba(10, 6, 16, 0.28),
        0 16px 36px rgba(10, 6, 16, 0.16);
}

:root[data-color-scheme="white"] {
    --canvas: #f5f0e8;
    --bg: #f5f0e8;
    --bg-card: #fdfbf6;
    --bg-surface: #e7e2da;
    --bg-surface-hover: #ddd8d0;
    --bg-overlay: rgba(245, 240, 232, 0.96);
    --border: rgba(0, 0, 0, 0.11);
    --border-light: rgba(0, 0, 0, 0.07);
    --text-1: rgba(0, 0, 0, 0.85);
    --text-2: rgba(0, 0, 0, 0.45);
    --text-3: rgba(0, 0, 0, 0.28);
    --accent: #887868;
    --accent-text: #786858;
    --accent-soft: rgba(136, 120, 104, 0.10);
    --accent-glow: rgba(136, 120, 104, 0.18);
    --accent-soft-bright: rgba(136, 120, 104, 0.20);
    --flash-border: rgba(0, 0, 0, 0.12);
    --flash-bg: rgba(0, 0, 0, 0.03);
    --card-bg: rgba(253, 251, 246, 0.85);
    --card-bg-solid: rgb(253, 251, 246);
    --card-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.60),
        0 1px 3px rgba(0, 0, 0, 0.05),
        0 4px 12px rgba(0, 0, 0, 0.04),
        0 16px 36px rgba(0, 0, 0, 0.025);
    --shimmer-color: rgba(255, 255, 255, 0.25);
    --replay-stroke: rgba(0, 0, 0, 0.14);
    --image-shadow:
        inset 0 0 0 1px rgba(0, 0, 0, 0.06),
        inset 0 2px 8px rgba(0, 0, 0, 0.10);
    --toggle-bg: rgba(0, 0, 0, 0.02);
    --toggle-border: rgba(0, 0, 0, 0.06);
    --toggle-hover-bg: rgba(0, 0, 0, 0.03);
    --toggle-hover-border: rgba(0, 0, 0, 0.12);
    --divider-color: rgba(0, 0, 0, 0.12);
    --answer-divider-color: rgba(0, 0, 0, 0.15);
}

:root[data-color-scheme="solarized"] {
    --canvas: #002d38;
    --bg: #002d38;
    --bg-card: #093946;
    --bg-surface: #184855;
    --bg-surface-hover: #205060;
    --bg-overlay: rgba(0, 45, 56, 0.96);
    --border: rgba(143, 170, 171, 0.10);
    --border-light: rgba(143, 170, 171, 0.14);
    --text-1: #98a8a8;
    --text-2: #657377;
    --text-3: rgba(101, 115, 119, 0.55);
    --accent: #2b90d8;
    --accent-text: #5aafe8;
    --accent-soft: rgba(43, 144, 216, 0.12);
    --accent-glow: rgba(43, 144, 216, 0.22);
    --accent-soft-bright: rgba(43, 144, 216, 0.20);
    --card-bg: rgba(9, 57, 70, 0.58);
    --card-bg-solid: rgb(9, 57, 70);
    --card-shadow:
        inset 0 1px 0 rgba(143, 170, 171, 0.06),
        0 1px 3px rgba(0, 30, 38, 0.40),
        0 4px 12px rgba(0, 30, 38, 0.28),
        0 16px 36px rgba(0, 30, 38, 0.16);
}

:root[data-color-scheme="solarized"],
:root[data-color-scheme="solarized-light"] {
    --pitch-atamadaka: #f23749;
    --pitch-heiban: #2b90d8;
    --pitch-nakadaka: #d56500;
    --pitch-kifuku: #7d80d1;
    --pitch-odaka: #819500;
    --pitch-keihan-heiban: #2b90d8;
    --pitch-keihan-low-heiban: #2b90d8;
    --pitch-keihan-atamadaka: #f23749;
    --pitch-keihan-nakadaka: #d56500;
    --pitch-keihan-low-nakadaka: #d56500;
    --pitch-keihan-odaka: #819500;
    --pitch-black: var(--text-1);
}

:root[data-color-scheme="solarized-light"] {
    --canvas: #fbf7ef;
    --bg: #fbf7ef;
    --bg-card: #fefdf9;
    --bg-surface: #f1e9d2;
    --bg-surface-hover: #e8dfc8;
    --bg-overlay: rgba(251, 247, 239, 0.96);
    --border: rgba(0, 0, 0, 0.10);
    --border-light: rgba(0, 0, 0, 0.06);
    --text-1: #5b7279;
    --text-2: #657377;
    --text-3: #8faaab;
    --accent: #2b90d8;
    --accent-text: #1a7abb;
    --accent-soft: rgba(43, 144, 216, 0.10);
    --accent-glow: rgba(43, 144, 216, 0.18);
    --accent-soft-bright: rgba(43, 144, 216, 0.18);
    --flash-border: rgba(0, 0, 0, 0.12);
    --flash-bg: rgba(0, 0, 0, 0.03);
    --card-bg: rgba(254, 253, 249, 0.85);
    --card-bg-solid: rgb(254, 253, 249);
    --card-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.60),
        0 1px 3px rgba(0, 0, 0, 0.05),
        0 4px 12px rgba(0, 0, 0, 0.04),
        0 16px 36px rgba(0, 0, 0, 0.025);
    --shimmer-color: rgba(255, 255, 255, 0.25);
    --replay-stroke: rgba(0, 0, 0, 0.14);
    --graph-color: #5b7279;
    --image-shadow:
        inset 0 0 0 1px rgba(0, 0, 0, 0.06),
        inset 0 2px 8px rgba(0, 0, 0, 0.10);
    --toggle-bg: rgba(0, 0, 0, 0.02);
    --toggle-border: rgba(0, 0, 0, 0.06);
    --toggle-hover-bg: rgba(0, 0, 0, 0.03);
    --toggle-hover-border: rgba(0, 0, 0, 0.12);
    --divider-color: rgba(0, 0, 0, 0.12);
    --answer-divider-color: rgba(0, 0, 0, 0.15);
}

/* — Card Transparency off: opaque card background — */
:root[data-card-transparency="off"] .card-inner {
    background: var(--card-bg-solid);
}

/* ── DEBUG: layout spacing visualization ── */
[data-debug="on"] .answer > *,
[data-debug="on"] .front-content > *,
[data-debug="on"] .word-column > *,
[data-debug="on"] .details-inner > *,
[data-debug="on"] .front > .audio-row,
[data-debug="on"] .back .audio-row {
    outline: 2px solid rgba(0, 150, 255, 0.6);
    background-color: rgba(0, 150, 255, 0.06);
}
[data-debug="on"] .answer,
[data-debug="on"] .front-content,
[data-debug="on"] .front,
[data-debug="on"] .back {
    outline: 2px dashed rgba(255, 150, 0, 0.6);
    background-color: rgba(255, 150, 0, 0.08);
}
[data-debug="on"] .debug-last {
    outline: 3px solid rgba(255, 0, 80, 0.8) !important;
    background-color: rgba(255, 0, 80, 0.12) !important;
}
[data-debug="on"] .word-pitch-group {
    outline: 2px dashed rgba(0, 200, 100, 0.6);
