@media (hover: none) {
    html {
        height: 100dvh;
        overflow: hidden;
    }

    #content {
        margin: 0;
    }

    .card {
        padding: 20px;
        min-height: auto;
        height: calc(100dvh - var(--bottom-inset, 0px) + 35px);
        overflow-y: auto;
    }

    .card-inner {
        min-height: calc(100dvh - 40px - var(--bottom-inset, 0px) + 35px + 1px);
    }

    .card-inner:has(> .back),
    html:not(.tategaki) .card-inner:has(.front-content [data-side="front"]) {
        padding-top: clamp(20px, 6vw, 44px);
    }

    /* AnkiDroid: revert iOS-only bottom-inset and bounce scroll adjustments */
    .android .card {
        height: 100dvh;
    }
    .android .card-inner {
        min-height: calc(100dvh - 40px);
    }
}

/* iPad / large touch screens — cap card height to phone-like size */
@media (hover: none) and (min-width: 768px) {
    .card {
        padding-bottom: calc(20px + var(--bottom-inset, 0px));
    }
    .card-inner {
        min-height: 650px;
    }
}

/* — Base — */

.card-inner {
    box-sizing: border-box;
    background: var(--card-bg);
    color: var(--text-1);
    font-family: var(--sans), var(--jp);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    padding: clamp(20px, 6vw, 44px);
    max-width: 580px;
    margin: 0 auto;
    border: 1px solid var(--border);
    border-radius: 16px;
    position: relative;
    overflow: hidden;
    box-shadow: var(--card-shadow);
    transform: translateZ(0);
}

/* Glass sheen on card surface */
.card-inner::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: radial-gradient(300px 250px at 50% 120px, var(--shimmer-color) 0%, transparent 100%);
    pointer-events: none;
    z-index: 0;
}

/* Grain on card surface */
.card-inner::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.75' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
    background-size: 180px;
    opacity: 0.035;
    pointer-events: none;
    z-index: 0;
}

/* Card contents above grain */
.card-inner > * {
    position: relative;
    z-index: 1;
}

.divider {
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--divider-color) 25%, var(--divider-color) 75%, transparent);
    margin: 0 0 16px;
}

/* Pitch graph */

.pitch-graph {
    text-align: center;
    margin: 0 0 20px;
    line-height: 0;
}

.pitch-graph svg {
    max-width: 100%;
    height: auto;
}

.pitch-graph.text-play svg {
    transform: scale(1.111);
    transform-origin: center top;
}

@media (hover: none) {
    .pitch-graph {
        margin: 0 0 12px;
    }
}

/* Utility roles — before accent colors so accents win when both apply */
.connector line { stroke: var(--graph-color); }
.particle circle { fill: none; stroke: var(--graph-color); }
.particle line { stroke: var(--graph-color); }
.particle text { fill: var(--graph-color); }

/* Pitch accent colors (SVG) */

.atamadaka circle,
.atamadaka line { fill: var(--pitch-atamadaka); stroke: var(--pitch-atamadaka); }
.atamadaka text { fill: var(--pitch-atamadaka); }

.heiban circle,
.heiban line { fill: var(--pitch-heiban); stroke: var(--pitch-heiban); }
.heiban text { fill: var(--pitch-heiban); }

.nakadaka circle,
.nakadaka line { fill: var(--pitch-nakadaka); stroke: var(--pitch-nakadaka); }
.nakadaka text { fill: var(--pitch-nakadaka); }

.kifuku circle,
.kifuku line { fill: var(--pitch-kifuku); stroke: var(--pitch-kifuku); }
.kifuku text { fill: var(--pitch-kifuku); }

.odaka circle,
.odaka line { fill: var(--pitch-odaka); stroke: var(--pitch-odaka); }
.odaka text { fill: var(--pitch-odaka); }

.black circle,
.black line { fill: var(--pitch-black); stroke: var(--pitch-black); }
.black text { fill: var(--pitch-black); }

/* Keihan pitch accent colors (SVG) */

.keihan_heiban circle,
.keihan_heiban line { fill: var(--pitch-keihan-heiban); stroke: var(--pitch-keihan-heiban); }
.keihan_heiban text { fill: var(--pitch-keihan-heiban); }

.keihan_low_heiban circle,
.keihan_low_heiban line { fill: var(--pitch-keihan-low-heiban); stroke: var(--pitch-keihan-low-heiban); }
.keihan_low_heiban text { fill: var(--pitch-keihan-low-heiban); }

.keihan_atamadaka circle,
.keihan_atamadaka line { fill: var(--pitch-keihan-atamadaka); stroke: var(--pitch-keihan-atamadaka); }
.keihan_atamadaka text { fill: var(--pitch-keihan-atamadaka); }

.keihan_nakadaka circle,
.keihan_nakadaka line { fill: var(--pitch-keihan-nakadaka); stroke: var(--pitch-keihan-nakadaka); }
.keihan_nakadaka text { fill: var(--pitch-keihan-nakadaka); }

.keihan_low_nakadaka circle,
.keihan_low_nakadaka line { fill: var(--pitch-keihan-low-nakadaka); stroke: var(--pitch-keihan-low-nakadaka); }
.keihan_low_nakadaka text { fill: var(--pitch-keihan-low-nakadaka); }

.keihan_odaka circle,
.keihan_odaka line,
.keihan_low_odaka circle,
.keihan_low_odaka line { fill: var(--pitch-keihan-odaka); stroke: var(--pitch-keihan-odaka); }
.keihan_odaka text,
.keihan_low_odaka text { fill: var(--pitch-keihan-odaka); }

/* Particle circles stay hollow even with accent colors */
.particle circle { fill: none; }

/* Text should not have stroke */
.atamadaka text,
.heiban text,
.nakadaka text,
.kifuku text,
.odaka text,
.black text,
.keihan_heiban text,
.keihan_low_heiban text,
.keihan_atamadaka text,
.keihan_nakadaka text,
.keihan_low_nakadaka text,
.keihan_odaka text,
.keihan_low_odaka text,
.connector text,
.particle text { stroke: none; }

/* Pitch accent colors (HTML spans) */

.particle { color: var(--graph-color); }
.atamadaka { color: var(--pitch-atamadaka); }
.heiban { color: var(--pitch-heiban); }
.nakadaka { color: var(--pitch-nakadaka); }
.kifuku { color: var(--pitch-kifuku); }
.odaka { color: var(--pitch-odaka); }
.black { color: var(--pitch-black); }
.keihan_heiban { color: var(--pitch-keihan-heiban); }
.keihan_low_heiban { color: var(--pitch-keihan-low-heiban); }
.keihan_atamadaka { color: var(--pitch-keihan-atamadaka); }
.keihan_nakadaka { color: var(--pitch-keihan-nakadaka); }
.keihan_low_nakadaka { color: var(--pitch-keihan-low-nakadaka); }
.keihan_odaka,
.keihan_low_odaka { color: var(--pitch-keihan-odaka); }
.target-word.no-accent span { color: var(--text-1) !important; }
.def.no-accent span { color: var(--text-1) !important; }
.notes.no-accent span { color: var(--text-1) !important; }
.def .particle { color: inherit; }
.target-word.no-pitch-color span { color: var(--text-1) !important; }
.target-word.no-pitch-color rt { color: var(--text-1) !important; }
.sentence.no-pitch-color span { color: var(--text-1) !important; }
.sentence.no-pitch-color rt { color: var(--text-1) !important; }
.def.no-pitch-color span { color: var(--text-1) !important; }

/* Devoiced markers are hollow */
circle.devoiced, rect.devoiced { fill: none !important; }
/* Per-role `.<role> circle, .<role> line` rules above don't target rect,
   so rect.devoiced (used for multi-char moras like しゅ) has no stroke
   source. Pick up the role color via inherited `color`. */
rect.devoiced { stroke: currentColor; }

/* — Replay button (targets Anki's generated .replay-button) — */

.replay-button {
    --rb-fill: var(--bg-surface);
    --rb-stroke: var(--replay-stroke);
    --rb-triangle: var(--text-2);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: none;
    border: none;
    padding: 0;
    margin: 0;
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    vertical-align: middle;
    line-height: 1;
}

@media (hover: hover) {
    .replay-button {
        transition: transform 180ms var(--spring);
    }
}

.replay-button svg {
    display: block;
    pointer-events: none;
}

/* Circle */
.replay-button svg circle,
.replay-button .replayCircle {
    fill: var(--rb-fill);
    stroke: var(--rb-stroke);
    stroke-width: 1.5;
    transition: stroke 200ms ease, fill 200ms ease;
}

/* Triangle — scale down Anki's oversized default path */
.replay-button svg path,
.replay-button .replayTriangle {
    fill: var(--rb-triangle);
    stroke: none;
    transition: fill 200ms ease;
    transform: scale(0.55);
    transform-origin: 32px 32px;
}

@media (hover: hover) {
    .replay-button:hover {
        transform: scale(1.06);
        --rb-fill: var(--bg-surface-hover);
        --rb-stroke: var(--accent-glow);
        --rb-triangle: var(--accent);
    }

    .replay-button:active {
        transform: scale(0.95);
        transition-duration: 80ms;
    }
}

.replay-button.highlight-touch {
    --rb-fill: var(--bg-surface-hover);
}

@media (hover: none) {
    .replay-button:active {
        --rb-fill: var(--bg-surface-hover);
    }
}

/* ================================================
   AUDIO ROW (always visible — front & back)
   ================================================ */

.audio-row {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: clamp(16px, 8vw, 40px);
}

.audio-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    flex: 1 1 0;
    max-width: 80px;
    min-width: 0;
    overflow: visible;
}

.audio-item .replay-button {
    width: 52px !important;
    height: 52px !important;
    overflow: hidden;
    font-size: 0;
}
.audio-item .replay-button svg,
.audio-item .replay-button img {
    width: 52px !important;
    height: 52px !important;
}

.audio-label {
    font-family: var(--mono);
    font-size: clamp(7px, 2.5vw, 10px);
    font-weight: 500;
    letter-spacing: 0.1em;
    color: var(--text-3);
    text-transform: uppercase;
    white-space: nowrap;
}

[data-audio-labels="off"] .audio-label {
    display: none;
}

/* Hide per-section audio buttons — keep autoplay & text-play functional */
.audio-item[data-btn-off] { display: none; }

/* Playing/highlight state — accent colors while audio is playing or button animating */
.replay-button.playing,
.replay-button.highlight {
    --rb-fill: var(--bg-surface-hover);
    --rb-stroke: var(--accent-glow);
    --rb-triangle: var(--accent);
}

@media (hover: hover) {
    .replay-button.hover-linked {
        --rb-fill: var(--bg-surface-hover);
        --rb-stroke: var(--accent-glow);
        --rb-triangle: var(--accent);
    }
}

/* ── Text-as-play-button ── */

.text-play {
    cursor: pointer;
    position: relative;
    isolation: isolate;
}

.text-play::after {
    content: '';
    position: absolute;
    inset: var(--pill-top, -2px) -6px -2px;
    border-radius: 6px;
    z-index: -1;
    transition: background 600ms ease, box-shadow 600ms ease;
}

.text-play.text-play-inert {
    pointer-events: none;
    cursor: default;
}

.tategaki .text-play::after {
    inset: -6px var(--pill-right, -4px) -6px -4px;
}

@media (hover: hover) {
    .text-play:hover::after,
    .text-play.hover-linked::after {
        background: color-mix(in srgb, var(--accent-soft) 75%, transparent);
        box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent-glow) 75%, transparent);
    }
}

.text-play.playing::after {
    background: var(--accent-soft-bright);
    box-shadow: inset 0 0 0 1px var(--accent-glow);
}

html:not(.tategaki) .word-pitch-group.text-play::after {
    inset: var(--pill-top, -6px) -8px -6px;
    border-radius: 10px;
}

.tategaki .word-pitch-group.text-play::after {
    inset: -8px var(--pill-right, -6px) -8px -6px;
    border-radius: 10px;
}

html:not(.tategaki) .pitch-graph.text-play {
    align-self: stretch;
}

html:not(.tategaki) .pitch-graph.text-play::after {
    inset: -4px -8px -4px;
    border-radius: 8px;
}

.tategaki .pitch-graph.text-play::after {
    inset: -8px var(--pill-right, -4px) -8px -4px;
    border-radius: 8px;
}

/* ── Pill position: per-element tuning variables ── */
.target-word.text-play      { --pill-ruby-hidden: 0.33em; --pill-ruby-visible: -2px; }
.sentence.text-play         { --pill-ruby-hidden: 0.2em;  --pill-ruby-visible: -0.22em; }
.def.text-play              { --pill-ruby-visible: -0.22em; }
.word-pitch-group.text-play { --pill-ruby-visible: -6px; }

/* ── Pill position: state resolution (non-tategaki) ── */

/* Ruby visible (answer area, back-revealed, furigana-front) */
html:not(.tategaki) .text-play:has(ruby):not(.furigana-off) {
    --pill-top: var(--pill-ruby-visible);
}

/* Split furigana: always visible even when furigana-off */
html:not(.tategaki) .text-play.furigana-off:has(rt[data-split]),
html:not(.tategaki) .text-play.furigana-off:has(rt[data-front]) {
    --pill-top: var(--pill-ruby-visible);
}

/* Front-side hidden furigana: pull pill inward past empty annotation space */
html:not(.tategaki) .front-content .text-play:has(ruby):not(.furigana-front):not(.furigana-off) {
    --pill-top: var(--pill-ruby-hidden);
}

/* Back side re-reveals furigana on front-content elements */
html:not(.tategaki) .back .front-content .text-play:has(ruby):not(.furigana-front):not(.furigana-off) {
    --pill-top: var(--pill-ruby-visible);
}

/* ── Pill position: state resolution (tategaki) ──
   Only "visible" needed — tategaki front hides rt with display:none,
   so no hidden-space adjustment needed. */
.tategaki .text-play:has(ruby):not(.furigana-off) {
    --pill-right: var(--pill-ruby-visible);
}
.tategaki .text-play.furigana-off:has(rt[data-split]),
.tategaki .text-play.furigana-off:has(rt[data-front]) {
    --pill-right: var(--pill-ruby-visible);
}

/* Front entrance */
.fi {
    animation: fadeIn 0.5s var(--spring) both;
    animation-delay: calc(var(--d, 0) * 1ms);
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(28px) scale(0.94); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes rowSettle {
    from { padding: 48px 0 0; gap: 40px; }
}

@keyframes btnSettle {
    from { width: 52px; height: 52px; }
}

@keyframes itemSettle {
    from { gap: 10px; }
}

@keyframes rtFadeIn {
    from { opacity: 0; }
    to   { opacity: 1; }
}

@keyframes frontFadeIn {
    from { opacity: 0; transform: translateY(12px); }
}

@keyframes colorReveal {
    from { color: var(--text-1); }
}

@keyframes labelSettle {
    from { font-size: 10px; }
}

/* Audio-only front: flex spacer positioning */
html:not(.tategaki) :not(.back) > .card-inner > .front:not(:has(.front-content [data-side="front"])) {
    display: flex;
    flex-direction: column;
    align-items: center;
}
html:not(.tategaki) :not(.back) > .card-inner > .front:not(:has(.front-content [data-side="front"]))::before,
html:not(.tategaki) :not(.back) > .card-inner > .front:not(:has(.front-content [data-side="front"]))::after {
    content: '';
    flex-grow: 1;
}
@media (hover: none) {
    html:not(.tategaki) :not(.back) > .card-inner:not(:has(> .back)) {
        display: flex;
        flex-direction: column;
    }
    html:not(.tategaki) :not(.back) > .card-inner:not(:has(> .back)):not(:has(.front-content [data-side="front"])) {
        padding: clamp(20px, 6vw, 44px);
    }
    html:not(.tategaki) :not(.back) > .card-inner > .front:not(:has(.front-content [data-side="front"])) {
        flex: 1;
    }
    html:not(.tategaki) :not(.back) > .card-inner > .front:not(:has(.front-content [data-side="front"]))::before {
        flex-grow: 2;
    }
    html:not(.tategaki) :not(.back) > .card-inner > .front:not(:has(.front-content [data-side="front"])) .audio-row {
        padding-top: 0;
        margin-bottom: 0;
    }
}

/* Audio-only back: flex spacer positioning */
html:not(.tategaki) .card-inner:has(> .back[data-audio-only]) {
    display: flex;
    flex-direction: column;
}
html:not(.tategaki) .back[data-audio-only] {
    flex: 1;
}
html:not(.tategaki) .back[data-audio-only]::before,
html:not(.tategaki) .back[data-audio-only]::after {
    content: '';
    flex-grow: 1;
}
html:not(.tategaki) .back[data-audio-only] .front-content {
    display: none;
}
html:not(.tategaki) .back[data-audio-only] .audio-row {
    padding: 48px 0 0;
    margin-bottom: 48px;
}
@media (hover: none) {
    html:not(.tategaki) .card-inner:has(> .back[data-audio-only]) {
        padding: clamp(20px, 6vw, 44px);
    }
    html:not(.tategaki) .back[data-audio-only]::before {
        flex-grow: 2;
    }
    html:not(.tategaki) .back[data-audio-only] .audio-row {
        padding-top: 0;
        margin-bottom: 0;
    }
    html:not(.tategaki) .back[data-audio-only] .audio-row-bottom {
        margin-bottom: 0;
    }
}

/* ================================================
   FRONT — centered audio with extra padding
   ================================================ */

.front .audio-row {
    padding: 48px 0 0;
    margin-bottom: 48px;
}

@media (hover: none) {
    .front .audio-row {
        margin-bottom: 16px;
    }
    .front .audio-item .replay-button {
        width: 68px !important;
        height: 68px !important;
    }
    .front .audio-item .replay-button svg,
    .front .audio-item .replay-button img {
        width: 68px !important;
        height: 68px !important;
    }
}

/* Front: move audio below content when content is on front */
html:not(.tategaki) :not(.back) > .card-inner > .front:has(.front-content [data-side="front"]) {
    display: flex;
    flex-direction: column;
}

html:not(.tategaki) :not(.back) > .card-inner > .front:has(.front-content [data-side="front"]) .audio-row {
    order: 1;
    padding-top: 0;
}

html:not(.tategaki) :not(.back) > .card-inner > .front:has(.front-content [data-side="front"]) .front-content {
    margin-bottom: 0;
}

/* ================================================
   BACK — compact audio controls + answer section
   ================================================ */

.back .audio-row {
    padding: 0;
    margin-bottom: 20px;
    gap: clamp(8px, 4vw, 20px);
    animation: rowSettle 0.35s var(--ease) both;
}

/* Audio item ordering — top row (desktop) */
.back .audio-row .audio-item[data-audio="word"] { order: 0; }
.back .audio-row .audio-item[data-audio="sentence"] { order: 1; }
.back .audio-row .audio-item[data-audio="def"] { order: 2; }

.back .audio-item {
    gap: 6px;
    animation: itemSettle 0.35s var(--ease) both;
}

.back .audio-item .replay-button {
    width: 40px !important;
    height: 40px !important;
    overflow: hidden;
    animation: btnSettle 0.3s var(--ease) 50ms both;
}
.back .audio-item .replay-button svg,
.back .audio-item .replay-button img {
    width: 40px !important;
    height: 40px !important;
    animation: btnSettle 0.3s var(--ease) 50ms both;
}

.back .audio-label {
    font-size: clamp(6.5px, 2.2vw, 9px);
    animation: labelSettle 0.35s var(--ease) both;
}

/* Mobile: skip layout-triggering settle animations (padding, gap, width, height,
   font-size all force reflow every frame — too expensive for mobile WebViews) */
@media (hover: none) {
    .back .audio-row {
        display: none;
    }

    .back .audio-row,
    .back .audio-item,
    .back .audio-item .replay-button,
    .back .audio-item .replay-button svg,
    .back .audio-item .replay-button img,
    .back .audio-label {
        animation: none;
    }
}

/* Unwrap {{FrontSide}} containers on back */
.back > .card-inner { display: contents; }
.back > .card-inner::before,
.back > .card-inner::after { display: none; }
.back .front { display: contents; }

html:not(.tategaki) .back {
    display: flex;
    flex-direction: column;
}

.back .audio-row:not(:has([data-side="front"]:not([data-btn-off]))) {
    display: none;
}

html:not(.tategaki) .back:not(:has(.audio-row [data-side="front"]:not([data-btn-off]))) .audio-row-bottom {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: clamp(8px, 4vw, 20px);
    margin-bottom: 20px;
    order: 3;
}
html:not(.tategaki) .back:not(:has(.audio-row [data-side="front"]:not([data-btn-off]))) .audio-row-bottom .audio-item[data-audio="word"] { order: 0; }
html:not(.tategaki) .back:not(:has(.audio-row [data-side="front"]:not([data-btn-off]))) .audio-row-bottom .audio-item[data-audio="sentence"] { order: 1; }
html:not(.tategaki) .back:not(:has(.audio-row [data-side="front"]:not([data-btn-off]))) .audio-row-bottom .audio-item[data-audio="def"] { order: 2; }

html:not(.tategaki) .back:has(.front-content [data-side="front"]) .front-content {
    order: -1;
}

/* Hide Anki's auto-injected answer separator */
.back > hr { display: none; }

/* Suppress front entrance animations on back */
.back .fi { animation: none; }

.back .audio-item.bi {
    animation: fadeIn 0.35s var(--spring) 70ms both,
               itemSettle 0.35s var(--ease) both;
}

@media (hover: none) {
    .back .audio-item.bi {
        animation: fadeIn 0.35s var(--spring) 70ms both;
    }
}

.answer {
    display: flex;
    flex-direction: column;
    margin-top: 0;
}

/* Target word — Japanese serif for kanji with ruby furigana */

.target-word {
    font-family: var(--jp-kyokasho);
    font-size: 52px;
    font-weight: 600;
    letter-spacing: 0.04em;
    line-height: 1.2;
    text-align: center;
    margin: 0 0 12px;
    text-rendering: optimizeLegibility;
}

.word-pitch-group > .target-word {
    margin-bottom: 0;
}
.word-pitch-group > .target-word.text-play {
    align-self: stretch;
}
.word-pitch-group > .pitch-graph {
    margin-bottom: 0;
}

/* Default: word-only spacing */
.word-pitch-group {
    margin-bottom: 12px;
}

/* When graph is visible: graph's spacing + internal gap */
.word-pitch-group:has(.pitch-graph:not([data-state="empty"]):not([style*="display: none"])) {
    gap: 8px;
    margin-bottom: 20px;
}

@media (hover: none) {
    .word-pitch-group:has(.pitch-graph:not([data-state="empty"]):not([style*="display: none"])) {
        margin-bottom: 12px;
    }
}

/* Collapse wrapper when all children are hidden */
.word-pitch-group:has(> .target-word[data-show="off"]):has(> .pitch-graph[data-state="empty"]) {
    display: none;
}

/* Ruby (furigana) base styles */

ruby {
    ruby-align: center;
}

/* Render ruby (Latin chars carrying furigana like T in T[ティー]シャツ, plus
   the rt itself) in the JP font in body-cascade contexts where the parent
   would otherwise route Latin to Inter. .target-word and .sentence already
   use a JP font on their own, so their ruby/rt inherits it without help. */
.def ruby, .notes ruby,
.def rt, .notes rt {
    font-family: var(--jp);
}

rt {
    font-weight: 400;
    color: var(--text-1);
}

.target-word rt {
    font-size: 0.33em;
    font-weight: 500;
    letter-spacing: 0;
    transform: translateY(0px);
    color: inherit;
}

html:not(.tategaki) .target-word:has(ruby):not(.furigana-off) {
    padding-top: 0.33em;
}

@media (hover: none) {
    @supports not (-webkit-touch-callout: none) {
        html:not(.tategaki) .target-word:has(ruby):not(.furigana-off) {
            padding-top: 0.38em;
        }
        html:not(.tategaki) .sentence:has(ruby):not(.furigana-off) {
            padding-top: 0.45em;
        }
        html:not(.tategaki) .def:not(.furigana-off) > .def-inner:has(ruby) {
            padding-top: 0.45em;
        }
    }
}

/* Image */

.image-wrap {
    width: 100%;
    border-radius: 10px;
    overflow: hidden;
    position: relative;
    margin-bottom: 16px;
}

.image-wrap::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    box-shadow: var(--image-shadow);
    pointer-events: none;
}

.image-wrap img {
    width: 100% !important;
    min-width: 100%;
    height: clamp(140px, 45vw, 220px);
    object-fit: cover;
    display: block;
}

.image-wrap.image-full {
    width: fit-content;
    margin-inline: auto;
}

.image-wrap.image-full img {
    width: auto !important;
    min-width: 0 !important;
    height: auto !important;
    max-height: clamp(140px, 45vw, 220px);
    max-width: 100%;
}

.image-wrap br {
    display: none;
}

.image-wrap:has(> svg) {
    width: auto;
}

/* Sentence-level furigana */

.sentence ruby {
    ruby-align: center;
}

.sentence rt {
    font-size: 0.5em;
    font-weight: 400;
    color: inherit;
    transform: translateY(-1px);
}

@media (hover: none) {
    .sentence rt {
        font-size: 0.45em;
        transform: translateY(7px);
    }
}

/* Sentence */

.sentence {
    font-family: var(--jp);
    font-size: 23px;
    font-weight: 400;
    line-height: 1.7;
    color: var(--text-1);
    text-align: center;
    margin: 0 0 20px;
}

.sentence .particle,
.notes .particle {
    color: inherit;
}
.particle.atamadaka { color: var(--pitch-atamadaka); }
.particle.heiban { color: var(--pitch-heiban); }
.particle.nakadaka { color: var(--pitch-nakadaka); }
.particle.kifuku { color: var(--pitch-kifuku); }
.particle.odaka { color: var(--pitch-odaka); }
.particle.black { color: var(--pitch-black); }

.sentence mark {
    background: var(--accent-soft);
    color: var(--accent-text);
    padding: 2px 5px;
    margin: 0 -2px;
    border-radius: 3px;
    font-weight: 500;
    text-decoration: none;
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
}

/* Definition */

.def {
    font-size: 20px;
    font-weight: 400;
    line-height: 1.45;
    color: var(--text-1);
    margin: 0 0 16px 0;
    text-align: var(--definition-align);
}

.def > .def-inner {
    min-height: 0;
    min-width: 0;
}

.def > .def-inner > :first-child {
    margin-top: 0;
}

.def > .def-inner > :last-child {
    margin-bottom: 0;
}

.def rt {
    color: inherit;
    transform: translateY(-1px);
}

@media (hover: none) {
    .def rt {
        transform: translateY(7px);
    }
}

.tategaki .def rt {
    font-size: 0.47em;
    letter-spacing: 0.1em;
}

@media (hover: none) {
    .tategaki .def rt {
        font-size: 0.5em;
        transform: translate(-5px, 1px);
    }
}

/* Definition section — per-language CSS toggle */

.def-section {
    display: flex;
    flex-direction: column;
    margin-top: 0;
    margin-bottom: 16px;
    text-align: var(--toggle-align);
}

.details-section {
    text-align: var(--toggle-align);
}

.def-toggle-input {
    position: absolute;
    width: 0;
    height: 0;
    opacity: 0;
    pointer-events: none;
}

.def-toggle-label {
    display: inline-flex;
    align-items: center;
    align-self: var(--toggle-align-flex, center);
    background: var(--toggle-bg);
    border: 1px solid var(--toggle-border);
    border-radius: 6px;
    padding: 6px 14px;
    font-family: var(--mono);
    font-size: 10px;
    font-weight: 500;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-3);
    cursor: pointer;
    transition: color 200ms ease, border-color 200ms ease, background 200ms ease;
    margin-top: 0;
    gap: 4px;
}

@media (hover: hover) {
    .def-toggle-label:hover {
        color: var(--text-1);
        border-color: var(--toggle-hover-border);
        background: var(--toggle-hover-bg);
    }
}

.def-toggle-label::after {
    content: '▸';
    font-size: 10px;
    transition: transform 200ms ease;
}

.def-toggle-input:checked + .def-toggle-label::after {
    transform: rotate(90deg);
}

.def[data-def-show="hidden"] {
    display: none;
}

.def[data-def-show="toggle"] {
    display: grid;
    grid-template-rows: 0fr;
    opacity: 0;
    pointer-events: none;
    margin-top: 4px;
    margin-bottom: 0;
    transition: grid-template-rows 250ms cubic-bezier(0.25, 0.1, 0.25, 1),
                opacity 180ms ease 30ms,
                margin-bottom 250ms cubic-bezier(0.25, 0.1, 0.25, 1);
}

.def[data-def-show="toggle"] > .def-inner {
    overflow: hidden;
    transition: overflow 0s 0s;
    transition-behavior: allow-discrete;
}

.def-section:has(#def-toggle:checked) .def[data-def-show="toggle"] {
    grid-template-rows: 1fr;
    opacity: 1;
    pointer-events: auto;
}

.def-section:has(#def-toggle:checked) .def[data-def-show="toggle"] > .def-inner {
    overflow: visible;
    transition: overflow 0s 250ms;
    transition-behavior: allow-discrete;
}

.def-section:not(:has(.def[data-def-show="toggle"])) > #def-toggle,
.def-section:not(:has(.def[data-def-show="toggle"])) > .def-toggle-label {
    display: none;
}

.def-section:not(:has(.def[data-def-show="inline"], .def[data-def-show="toggle"])) {
    display: none;
}

.def-section:not(:has(.def[data-def-show="toggle"])) > .def[data-def-show="inline"] {
    margin-bottom: 0;
}

.def[data-def-show="inline"] {
    order: 1;
}

#def-toggle,
.def-toggle-label {
    order: 2;
}

.def[data-def-show="toggle"] {
    order: 3;
}


/* Data-attribute driven visibility */
[data-state="empty"] {
    display: none;
}

[data-show="off"] {
    display: none;
}

.audio-item[data-side="off"] { display: none; }

/* Front-content on back: visible when it has front-zone items */
.back .front-content {
    margin-top: 0;
    margin-bottom: 0;
}

/* Hide front-content children not designated for front */
.back .front-content [data-side="back"],
.back .front-content [data-side="off"] {
    display: none;
}

/* Collapse entire front-content when nothing is on front */
.back .front-content:not(:has([data-side="front"])) {
    display: none;
}

/* Front only: hide back-designated content and audio items.
   Scoped via :not(.back) > .card-inner so it doesn't apply on the back
   where .front has display:contents but is still in the DOM tree. */
:not(.back) > .card-inner > .front [data-side="back"],
:not(.back) > .card-inner > .front [data-side="off"] {
    display: none;
}
:not(.back) > .card-inner > .front .audio-row:not(:has(.audio-item[data-side="front"]:not([data-btn-off]))) {
    display: none;
}
/* Front-content base layout */
.front-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-top: 0;
}

.front-content .target-word {
    color: var(--text-1);
    margin: 0 0 12px;
    align-self: stretch;
}

.front-content .target-word rt {
    color: var(--text-1);
    visibility: hidden;
}

.front-content .sentence {
    color: var(--text-1);
    margin: 0 0 16px;
    align-self: stretch;
}

.front-content .sentence rt {
    color: var(--text-1);
    visibility: hidden;
}

/* furigana-front: show rt on front side (override default hiding) */
.front-content .target-word.furigana-front rt { visibility: visible; color: inherit; }
.front-content .sentence.furigana-front rt { visibility: visible; color: inherit; }
/* Suppress fade-in animation when furigana was already visible on front */
.back .front-content .target-word.furigana-front rt,
.back .front-content .sentence.furigana-front rt { opacity: 1; }
.back .front-content .target-word.furigana-front rt.rt-ri,
.back .front-content .sentence.furigana-front rt.rt-ri { animation: none; }

/* furigana-off: hide rt everywhere, including back-side reveal */
.target-word.furigana-off rt,
.sentence.furigana-off rt,
.def.furigana-off rt { display: none !important; }

/* Split furigana: always visible on front */
.front-content .target-word rt[data-split],
.front-content .sentence rt[data-split],
.front-content .target-word rt[data-front],
.front-content .sentence rt[data-front] {
    visibility: visible;
}

/* Override furigana-off for split furigana */
.target-word.furigana-off rt[data-split],
.sentence.furigana-off rt[data-split],
.target-word.furigana-off rt[data-front],
.sentence.furigana-off rt[data-front] {
    display: inline !important;
    visibility: visible !important;
}

.front-content .image-wrap {
    margin-bottom: 16px;
}

html:not(.tategaki) .front-content .image-wrap {
    order: -1;
}

/* Animate front-content children on the front side only */
:not(.back) > .card-inner > .front .front-content .image-wrap[data-side="front"] {
    animation: frontFadeIn 0.35s ease both;
}
:not(.back) > .card-inner > .front .front-content .target-word[data-side="front"] {
    animation: frontFadeIn 0.35s ease 80ms both;
}
:not(.back) > .card-inner > .front .front-content .sentence[data-side="front"] {
    animation: frontFadeIn 0.35s ease 160ms both;
}

/* Collapse empty children so margins don't create dead space */
.target-word:empty,
.sentence:empty,
.image-wrap:empty {
    display: none;
}

/* Back-side: upgrade front-content from plain white to colorized */
.back .front-content .target-word {
    color: inherit;
}
.back .front-content .target-word span {
    animation: colorReveal 0.35s ease both;
}
.back .front-content .target-word rt {
    color: inherit;
    visibility: visible;
    opacity: 0;
}
.back .front-content .target-word rt.rt-ri {
    animation: rtFadeIn 0.25s ease both;
}
.back .front-content .sentence {
    color: inherit;
}
.back .front-content .sentence span {
    animation: colorReveal 0.35s ease both;
}
.back .front-content .sentence rt {
    color: inherit;
    visibility: visible;
    opacity: 0;
}
.back .front-content .sentence rt.rt-ri {
    animation: rtFadeIn 0.25s ease both;
}

/* pitch-color-front: allow accent colors on front side */
.front-content .target-word.pitch-color-front { color: inherit; }
.front-content .sentence.pitch-color-front { color: inherit; }
/* Suppress color-reveal animation (colors were already visible on front) */
.back .front-content .target-word.pitch-color-front span,
.back .front-content .sentence.pitch-color-front span { animation: none; }

.def {
    line-height: 1.65;
}

/* Notes section */
.notes-section {
    margin-bottom: 16px;
}

.notes {
    font-size: 20px;
    font-weight: 400;
    line-height: 1.45;
    color: var(--text-1);
    margin: 0;
    text-align: var(--notes-align);
}

/* Details section — collapsible container for elements with details toggle on */
.details-section {
    order: 2;
    margin-bottom: 16px;
}

.details-input {
    position: absolute;
    width: 0;
    height: 0;
    opacity: 0;
    pointer-events: none;
}

.details-toggle {
    display: inline-flex;
    align-items: center;
    background: var(--toggle-bg);
    border: 1px solid var(--toggle-border);
    border-radius: 6px;
    padding: 6px 14px;
    font-family: var(--mono);
    font-size: 10px;
    font-weight: 500;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-3);
    cursor: pointer;
    transition: color 200ms ease, border-color 200ms ease, background 200ms ease;
    gap: 4px;
}

@media (hover: hover) {
    .details-toggle:hover {
        color: var(--text-1);
        border-color: var(--toggle-hover-border);
        background: var(--toggle-hover-bg);
    }
}

.details-toggle::after {
    content: '▸';
    font-size: 10px;
    transition: transform 200ms ease;
}

.details-input:checked + .details-toggle::after {
    transform: rotate(90deg);
}

.details-wrap {
    display: grid;
    grid-template-rows: 0fr;
    opacity: 0;
    pointer-events: none;
    margin-top: 4px;
    transition: grid-template-rows 250ms cubic-bezier(0.25, 0.1, 0.25, 1), opacity 180ms ease 30ms;
}

.details-inner {
    overflow: hidden;
    min-height: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
    transition: overflow 0s 0s;
    transition-behavior: allow-discrete;
}

.details-input:not(:checked) ~ .details-wrap .details-inner > * {
    padding: 0;
    margin: 0;
}

.details-input:checked ~ .details-wrap {
    grid-template-rows: 1fr;
    opacity: 1;
    pointer-events: auto;
}

.details-input:checked ~ .details-wrap .details-inner {
    overflow: visible;
    transition: overflow 0s 250ms;
    transition-behavior: allow-discrete;
}

/* Details inner element styling */
.details-inner .word-pitch-group.text-play,
.details-inner .target-word.text-play,
.details-inner .sentence.text-play {
    align-self: stretch;
}

.details-inner .word-pitch-group,
.details-inner .word-pitch-group:has(.pitch-graph:not([data-state="empty"]):not([style*="display: none"])) {
    margin-bottom: 0;
}

.details-inner .target-word {
    margin: 0;
}

.details-inner .pitch-graph {
    margin: 0;
}

.details-inner .image-wrap {
    order: unset;
}

.details-inner .sentence {
    margin: 0;
    text-align: center;
}

.details-inner .notes-section {
    margin: 0;
    order: unset;
    align-self: stretch;
}

.details-inner > .def {
    margin: 0;
    order: unset;
}

.details-inner.details-inner .def-section {
    display: flex;
    margin: 0;
    order: unset;
}

.details-inner .audio-item {
    display: flex;
    align-items: center;
    gap: 6px;
}

/* Audio item ordering — bottom row (mobile) */
.audio-row-bottom .audio-item[data-audio="word"] { order: 0; }
.audio-row-bottom .audio-item[data-audio="sentence"] { order: 1; }
.audio-row-bottom .audio-item[data-audio="def"] { order: 2; }

/* Bottom audio row — mobile only duplicate */

.audio-row-bottom {
    display: none;
}

@media (hover: none) {
    .audio-row-bottom {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: clamp(8px, 4vw, 20px);
        margin-top: 0;
        margin-bottom: 20px;
    }

    .audio-row-bottom .audio-item {
        gap: 6px;
    }

    .audio-row-bottom .audio-item .replay-button {
        width: 50px !important;
        height: 50px !important;
    }

    .audio-row-bottom .audio-item .replay-button svg {
        width: 50px !important;
        height: 50px !important;
    }

    .audio-row-bottom .audio-label {
        font-size: clamp(6.5px, 2.2vw, 9px);
    }
}

/* Word column — wraps target-word, pitch-graph, image; invisible in normal mode */
.word-column {
    display: contents;
}

.word-pitch-group {
    display: flex;
    flex-direction: column;
    align-items: center;
}

/* Non-tategaki: show image before word (image is before sentence in DOM) */
html:not(.tategaki) .answer .image-wrap {
    order: -1;
}
html:not(.tategaki) .answer .audio-row-bottom {
    order: -3;
}
html:not(.tategaki) .answer .def-section,
html:not(.tategaki) .answer .notes-section {
    order: 1;
}
html:not(.tategaki) .answer .details-section {
    order: 2;
}

/* Non-tategaki: Japanese text line-height */
html:not(.tategaki) .sentence,
html:not(.tategaki) .def {
    line-height: 1.7;
}

/* Back entrance animation — elements start hidden, JS adds .ri after content is ready */

.answer > [style*="--d"],
.word-column [style*="--d"] {
    opacity: 0;
}

.ri {
    animation: reveal 0.5s var(--spring) both;
    animation-delay: calc(var(--d, 0) * 1ms);
}

html:not(.tategaki) .answer .image-wrap.ri {
    animation-delay: 0ms;
}

@keyframes reveal {
    from {
        opacity: 0;
        transform: translateY(36px) scale(0.92);
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

@keyframes tategakiExpand {
    from { clip-path: inset(0 30% 0 30%); }
    to   { clip-path: inset(0); }
}

@keyframes tategakiReveal {
    from { opacity: 0; transform: translate(-16px, 0) scale(0.95); }
    to   { opacity: 1; transform: translate(0, 0) scale(1); }
}


@keyframes tategakiBtnSettle {
    from { transform: scale(1.04); }
}

@media (hover: none) {
    @keyframes tategakiBtnSettle {
        from { transform: scale(1.36); }
    }
}

/* ================================================
   TATEGAKI (vertical writing) mode
   ================================================ */

/* Card shrinks to fit content horizontally in vertical writing mode */
html.tategaki {
    direction: rtl;
}

.tategaki .card-inner {
    writing-mode: vertical-rl;
    direction: ltr;
    max-width: none;
    padding: 44px;
    height: min(calc(100vh - 80px), 668px);
}

.tategaki .card-inner::after {
    bottom: auto;
    height: min(calc(100vh - 80px), 668px);
    background: radial-gradient(300px 250px at 50% 50%, var(--shimmer-color) 0%, transparent 100%);
}

/* Hide front card for one frame so JS can populate content before paint */
.tategaki .card-inner:not(:has(> .back)) {
    animation: tateFrontReveal 0s 16ms both;
}
@keyframes tateFrontReveal {
    from { opacity: 0; }
    to   { opacity: 1; }
}

.tategaki .card-inner:has(> .back) {
    overflow: visible;
    clip-path: inset(0 30% 0 30%);
}
.tategaki .card-inner:not(:has(> .back)) {
    overflow: visible;
}
.tategaki .card-inner.tate-expand {
    clip-path: none;
    animation: tategakiExpand 100ms cubic-bezier(0.12, 0.8, 0.3, 1) both;
}

/* Extend grain pseudo into overflow to create scroll-end spacing;
   clip the grain to the card-inner bounds so the gap shows plain card background */
.tategaki .card-inner::before {
    left: -20px;
    clip-path: inset(0 0 0 20px round 16px);
}

.tategaki .back {
    height: 100%;
}

/* Re-assert display:contents on FrontSide's inner card-inner */
.tategaki .back > .card-inner {
    display: contents;
}

/* Front — .front stays in inherited vertical-rl to avoid orthogonal flow
   sizing collapse when audio-row is hidden and front-content starts empty.
   flex-direction:row in v-rl = top→bottom; align-items:flex-start = right. */
.tategaki .card-inner:not(:has(> .back)) .front {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    height: 100%;
}

/* Tategaki audio-only front: zero margin when audio is alone */
.tategaki :not(.back) > .card-inner:not(:has(> .back))
    .front:not(:has(.front-content [data-side="front"])):not(:has(.image-wrap[data-side="front"])) .audio-row {
    margin-left: 0;
}

/* Tategaki audio-only front: flex spacers push buttons ~2/3 down on mobile */
@media (hover: none) {
    .tategaki :not(.back) > .card-inner:not(:has(> .back))
        .front:not(:has(.front-content [data-side="front"])):not(:has(.image-wrap[data-side="front"])) {
        writing-mode: horizontal-tb;
        flex-direction: column;
        flex-wrap: nowrap;
        align-items: center;
    }
    .tategaki :not(.back) > .card-inner:not(:has(> .back))
        .front:not(:has(.front-content [data-side="front"])):not(:has(.image-wrap[data-side="front"]))::before {
        content: '';
        flex-grow: 2;
        order: -2;
    }
    .tategaki :not(.back) > .card-inner:not(:has(> .back))
        .front:not(:has(.front-content [data-side="front"])):not(:has(.image-wrap[data-side="front"]))::after {
        content: '';
        flex-grow: 1;
        order: 0;
    }
    .tategaki :not(.back) > .card-inner:not(:has(> .back))
        .front:not(:has(.front-content [data-side="front"])):not(:has(.image-wrap[data-side="front"])) .audio-row {
        margin-top: 0;
        margin-left: 0;
        padding-top: 0;
        margin-bottom: 0;
    }
    .tategaki :not(.back) > .card-inner:not(:has(> .back))
        .front:not(:has(.front-content [data-side="front"])):not(:has(.image-wrap[data-side="front"])) .front-content {
        display: none;
    }
}

/* Tategaki audio-only back: hide non-audio elements, reset heights */
.tategaki .back[data-audio-only] .front-content {
    display: none;
}
.tategaki .back[data-audio-only] .divider {
    display: none;
}
.tategaki .back[data-audio-only] .answer {
    writing-mode: horizontal-tb;
    flex-direction: column;
    flex-wrap: nowrap;
    align-items: center;
    height: auto;
    gap: clamp(12px, 6.15vw, 31px);
}
.tategaki .back[data-audio-only] .audio-row-bottom {
    height: auto;
    margin: 0;
}
.tategaki .back[data-audio-only] .word-column {
    height: auto;
    margin: 0;
}
.tategaki .back[data-audio-only] .mid-audio-row {
    grid-auto-flow: row;
    gap: clamp(12px, 6.15vw, 31px);
}

/* Tategaki audio-only back: flex spacers push buttons ~2/3 down on mobile */
@media (hover: none) {
    .tategaki .back[data-audio-only] {
        writing-mode: horizontal-tb;
        display: flex;
        flex-direction: column;
        align-items: center;
    }
    .tategaki .back[data-audio-only]::before {
        content: '';
        flex-grow: 2;
    }
    .tategaki .back[data-audio-only]::after {
        content: '';
        flex-grow: 1;
    }
    .tategaki .back[data-audio-only] .answer {
        flex-wrap: nowrap;
        flex-direction: column;
        align-items: center;
    }
    .tategaki .back[data-audio-only] .audio-row-bottom {
        padding-top: 0;
    }
}

/* On back side, .front must stay display:contents — the :not(:has(> .back))
   selector above also matches the inner .card-inner from {{FrontSide}},
   so we override it here with equal specificity (0-4-0), winning by source order. */
.tategaki .back .card-inner .front {
    display: contents;
}

.tategaki .front-content {
    writing-mode: horizontal-tb;
    text-align: center;
    margin-top: 0;

}

/* Front side: front-content uses vertical-rl so sentence (and other children)
   flow vertically by default; individual items opt out with horizontal-tb. */
.tategaki .card-inner:not(:has(> .back)) .front-content {
    writing-mode: vertical-rl;
    align-self: stretch;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 0;
    height: 100%;
}

/* Back side: same vertical-rl flex layout so items wrap into columns
   the same way as on the front (e.g. word+image stack when alone,
   but separate into columns when sentence is also present). */
.tategaki .back .front-content {
    writing-mode: vertical-rl;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 0;
    height: 100%;
}

/* Word + image on front, no sentence → push to opposite ends */
.tategaki .front-content:has(.target-word[data-side="front"]):has(.image-wrap[data-side="front"]):not(:has(.sentence[data-side="front"])) {
    justify-content: space-between;
}
.tategaki .front-content:has(.target-word[data-side="front"]):has(.image-wrap[data-side="front"]):not(:has(.sentence[data-side="front"])) .target-word {
    margin-left: 0;
    align-self: center;
}

.tategaki .front-content .target-word { margin-left: 16px; text-align: start; flex: 1; }
.tategaki .front-content .image-wrap { margin-left: 16px; }

/* Fully collapse furigana on the front in tategaki — visibility:hidden still
   reserves ruby-annotation space, which throws off vertical margins. */
.tategaki .front-content .target-word rt,
.tategaki .front-content .sentence rt {
    display: none;
}
.tategaki .back .front-content .target-word rt,
.tategaki .back .front-content .sentence rt {
    display: revert;
    animation: none;
    opacity: 1;
}
.tategaki .front-content .target-word.furigana-front rt,
.tategaki .front-content .sentence.furigana-front rt { display: revert; }
.tategaki .front-content .target-word rt[data-split],
.tategaki .front-content .sentence rt[data-split],
.tategaki .front-content .target-word rt[data-front],
.tategaki .front-content .sentence rt[data-front] { display: revert; }

.pitch-num {
  font-family: "Hiragino Mincho ProN", "PitchNum";
  font-feature-settings: "nalt" 9;
  font-size: 1em;
  vertical-align: baseline;
}
.pitch-num .bk {
  font-size: 0;
  font-style: normal;
}

/* Reset flex order inside front-content — .tategaki .sentence sets order:-3
   for the back's .answer layout, but front-content should use HTML order. */
.tategaki .front-content .sentence {
    order: 0;
}

.tategaki .front .audio-row {
    writing-mode: horizontal-tb;
    flex-direction: column;
    gap: clamp(16px, 8vw, 40px);
    padding: 0;
    order: -1;
    margin-left: 16px;
}

/* Back — hide the top audio row (audio-row-bottom takes over) */
.tategaki .back .front .audio-row {
    display: none;
}

/* Tategaki: image-only front — stack image and audio vertically */
.tategaki :not(.back) > .card-inner:not(:has(> .back)) .front:has(.image-wrap[data-side="front"]):not(:has(.target-word[data-side="front"])):not(:has(.sentence[data-side="front"])) {
    writing-mode: horizontal-tb;
    flex-direction: column;
    flex-wrap: nowrap;
    align-items: center;
    gap: 0;
}

.tategaki :not(.back) > .card-inner:not(:has(> .back)) .front:has(.image-wrap[data-side="front"]):not(:has(.target-word[data-side="front"])):not(:has(.sentence[data-side="front"])) .front-content {
    writing-mode: horizontal-tb;
    height: auto;
    align-self: auto;
}

.tategaki :not(.back) > .card-inner:not(:has(> .back)) .front:has(.image-wrap[data-side="front"]):not(:has(.target-word[data-side="front"])):not(:has(.sentence[data-side="front"])) .front-content .image-wrap {
    margin-left: 0;
}

/* Desktop: audio at top (order:-1), image below. Audio stretches to fill. */
.tategaki :not(.back) > .card-inner:not(:has(> .back)) .front:has(.image-wrap[data-side="front"]):not(:has(.target-word[data-side="front"])):not(:has(.sentence[data-side="front"])) .audio-row {
    flex: 1;
    margin-top: 0;
    margin-bottom: 0;
}

.tategaki :not(.back) > .card-inner:not(:has(> .back)) .front:has(.image-wrap[data-side="front"]):not(:has(.target-word[data-side="front"])):not(:has(.sentence[data-side="front"])) .audio-row .audio-item {
    flex: 0 0 auto;
}

/* Mobile: image at top, audio at bottom */
@media (hover: none) {
    .tategaki :not(.back) > .card-inner:not(:has(> .back)) .front:has(.image-wrap[data-side="front"]):not(:has(.target-word[data-side="front"])):not(:has(.sentence[data-side="front"])) .audio-row {
        order: 1;
    }
}

/* Answer — flex layout: audio right, content left */
.tategaki .answer {
    display: flex;
    flex-wrap: wrap;
    gap: 0;
    height: 100%;
    margin-top: 0;
    padding-bottom: 0;
}

@media (hover: none) {
    .tategaki .card {
        overflow-y: hidden;
        overscroll-behavior-y: none;
        touch-action: pan-x;
        padding-bottom: 20px;
    }
    .tategaki #content {
        margin: 0;
    }
    .tategaki .card-inner {
        height: calc(100dvh - max(40px, var(--bottom-inset, 0px) + 7px));
        min-height: 0;
        padding: clamp(20px, 6vw, 44px);
    }
    .tategaki .front {
        box-sizing: border-box;
    }
    .tategaki .front .audio-row {
        margin-top: auto;
        margin-bottom: 0;
    }
}

/* iPad tategaki — cap card height like desktop */
@media (hover: none) and (min-width: 768px) {
    .tategaki .card-inner {
        height: min(668px, calc(100dvh - max(40px, var(--bottom-inset, 0px) + 20px)));
    }
}

/* Audio column — directly left of sentence (mirrors front layout) */
.tategaki .audio-row-bottom {
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    align-items: center;
    writing-mode: horizontal-tb;
    order: -3;
    gap: clamp(12px, 6.15vw, 31px);
    margin: 0 0 0 24px;
    height: 100%;
}

.tategaki .audio-row-bottom .audio-item { flex: 0 0 auto; }
.tategaki .audio-row-bottom .audio-item[data-audio="word"] { order: 0; }
.tategaki .audio-row-bottom .audio-item[data-audio="sentence"] { order: 1; }
.tategaki .audio-row-bottom .audio-item[data-audio="def"] { order: 2; }

.tategaki .audio-row-bottom .audio-item .replay-button {
    width: 52px !important;
    height: 52px !important;
}

.tategaki .audio-row-bottom .audio-item .replay-button svg {
    width: 52px !important;
    height: 52px !important;
}

.tategaki .audio-row-bottom .audio-label {
    font-size: 9px;
}

@media (hover: none) {
    .tategaki .audio-row-bottom {
        justify-content: flex-start;
        box-sizing: border-box;
        padding-top: min(
            calc((100dvh - var(--bottom-inset, 0px) - 120px) * 0.52),
            calc(100dvh - max(40px, var(--bottom-inset, 0px) + 7px) - 88px - 260px)
        );
    }
    .android.tategaki .audio-row-bottom {
        padding-top: min(
            calc((100dvh - 120px) * 0.52),
            calc(100dvh - 388px)
        );
    }
}
@media (hover: none) and (min-width: 768px) {
    .tategaki .audio-row-bottom {
        padding-top: calc((min(668px, 100dvh - max(40px, var(--bottom-inset, 0px) + 20px)) - 120px) * 0.52);
    }
}

/* Hide empty audio column in tategaki (all audio routed to mid-audio-row) */
.tategaki .audio-row-bottom:empty {
    display: none;
}

/* Word column — word+graph at top, image at bottom */
.tategaki .word-column {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    align-content: flex-end;
    justify-content: space-between;
    order: 0;
    row-gap: 24px;
    column-gap: 18px;
    height: 100%;
    margin-left: 16px;
}

.tategaki .word-column > * {
    writing-mode: horizontal-tb;
}

.tategaki .target-word {
    letter-spacing: 0;
    margin: 0;
}

.tategaki .target-word:has(ruby):not(.furigana-off) {
    padding-right: 0.33em;
}

.tategaki .sentence:has(ruby):not(.furigana-off) {
    padding-right: 0.38em;
}

.tategaki .def:not(.furigana-off) > .def-inner:has(ruby) {
    padding-right: 0.35em;
}

@media (hover: none) {
    @supports not (-webkit-touch-callout: none) {
        .tategaki .target-word:has(ruby):not(.furigana-off) {
            padding-right: 0.38em;
        }
        .tategaki .sentence:has(ruby):not(.furigana-off) {
            padding-right: 0.45em;
        }
    }
}

/* WebKit (AnkiMobile) already expands the content area for ruby,
   so the extra padding is partially redundant. */
@supports (-webkit-touch-callout: none) {
    /* iOS WebKit's ruby layout adds annotation-gap space that inflates line
       boxes (~10-12 px per line).  Negative margin-block on rt collapses
       that gap; transform is adjusted from the mobile default (7px) to -3px
       to keep furigana visually above the base text. */
    /* iPhone default — furigana slightly closer to base text */
    html:not(.tategaki) .sentence rt,
    html:not(.tategaki) .def rt {
        margin-block: -0.5em;
        transform: translateY(0.25em);
    }
    /* Tategaki equivalent: margin-block collapses the horizontal annotation
       gap (in vertical-rl, block axis = horizontal).  Transforms adjusted
       from mobile defaults to compensate. */
    .tategaki .sentence rt {
        margin-block: -0.5em;
        transform: translate(-0.15em, 0.07em);
    }
    .tategaki .def rt {
        margin-block: -0.5em;
        transform: translate(-0.1em, 0.07em);
    }
    /* iPad — larger annotation gap needs more offset */
    @media (min-width: 768px) {
        html:not(.tategaki) .sentence rt,
        html:not(.tategaki) .def rt {
            transform: translateY(-0.35em);
        }
        .tategaki .sentence rt {
            transform: translate(0.35em, 0.07em);
        }
        .tategaki .def rt {
            transform: translate(0.4em, 0.07em);
        }
    }
    html:not(.tategaki) .target-word:has(ruby):not(.furigana-off) {
        padding-top: 0.08em;
    }
    html:not(.tategaki) .sentence:has(ruby):not(.furigana-off),
    html:not(.tategaki) .def:not(.furigana-off) > .def-inner:has(ruby) {
        padding-top: 0.2em;
    }
    .tategaki .target-word:has(ruby):not(.furigana-off) {
        padding-right: 0;
    }
    .tategaki .sentence:has(ruby):not(.furigana-off),
    .tategaki .def:not(.furigana-off) > .def-inner:has(ruby) {
        padding-right: 0.25em;
    }
    /* Pill position: iOS overrides (non-tategaki) */
    .target-word.text-play  { --pill-ruby-hidden: 0.45em; --pill-ruby-visible: 0.1em; }
    .sentence.text-play     { --pill-ruby-hidden: 0.35em; --pill-ruby-visible: 0.1em; }
    .def.text-play          { --pill-ruby-visible: 0.1em; }
    .word-pitch-group.text-play { --pill-ruby-visible: 0.1em; }

    /* Pill position: iOS overrides (tategaki) */
    .tategaki .target-word.text-play  { --pill-ruby-visible: -0.04em; }
    .tategaki .sentence.text-play,
    .tategaki .def.text-play          { --pill-ruby-visible: 0.1em; }
}

/* Collapse ruby-annotation padding when rt is hidden on tategaki front —
   the JS adds .furigana-hidden in the default "back only" state.
   Placed after all other tategaki padding rules to win source-order ties. */
.tategaki .front-content .target-word.furigana-hidden:has(ruby),
.tategaki .front-content .sentence.furigana-hidden:has(ruby) {
    padding-right: 0;
}
.tategaki .pitch-graph {
    margin: 0;
}

.tategaki .pitch-graph svg {
    max-width: 100%;
    height: auto;
}

.tategaki .word-pitch-group {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: auto;
    max-width: 391px;
    align-self: stretch;
    margin-left: 0;
}

/* Tategaki: mid audio row inside word column (between pitch graph and image) */
.tategaki .mid-audio-row {
    display: grid;
    grid-auto-flow: column;
    grid-template-rows: repeat(1, minmax(76px, auto));
    place-content: center;
    place-items: start center;
    flex-grow: 1;
    flex-basis: 0;
    row-gap: 12px;
    column-gap: clamp(16px, 8vw, 40px);
    margin: 0;
    will-change: transform;
    direction: rtl;

}

.tategaki .mid-audio-row .audio-item {
    gap: 6px;
    direction: ltr;
}
.tategaki .mid-audio-row .audio-item[data-audio="word"] { order: -2; }
.tategaki .mid-audio-row .audio-item[data-audio="sentence"] { order: -1; }
.tategaki .mid-audio-row .audio-item[data-audio="def"] { order: 0; }

.tategaki .mid-audio-row .replay-button {
    width: 52px !important;
    height: 52px !important;
}

.tategaki .mid-audio-row .replay-button svg {
    width: 52px !important;
    height: 52px !important;
}

.tategaki .mid-audio-row .audio-label {
    font-size: 9px;
}

.tategaki .image-wrap {
    width: 391px;
    margin-left: 0;
    margin-bottom: 0;
}

.tategaki .image-wrap:has(> svg) {
    width: auto;
}

.tategaki .image-wrap img {
    width: 100% !important;
    min-width: 100%;
    height: 220px;
    object-fit: cover;
}

.tategaki .image-wrap.image-full {
    width: fit-content;
}

.tategaki .image-wrap.image-full img {
    width: auto !important;
    min-width: 0 !important;
    height: auto !important;
    max-height: 220px;
    max-width: 391px;
}

@media (hover: none) {
    .tategaki .word-pitch-group {
        max-width: clamp(249px, 80vw, 391px);
    }
    .tategaki .image-wrap {
        width: clamp(249px, 80vw, 391px);
    }
    .tategaki .image-wrap img {
        width: 100% !important;
        min-width: 100%;
        height: clamp(140px, 45vw, 220px);
        max-height: none;
        object-fit: cover;
    }
    .tategaki .image-wrap.image-full {
        width: fit-content;
    }
    .tategaki .image-wrap.image-full img {
        width: auto !important;
        min-width: 0 !important;
        height: auto !important;
        max-height: clamp(140px, 45vw, 220px);
        max-width: clamp(249px, 80vw, 391px);
    }
    .tategaki .pitch-graph svg {
        max-width: clamp(249px, 80vw, 391px);
    }
}

/* Sentence — right after audio buttons */
.tategaki .sentence {
    text-align: start;
    margin: 0 0 0 16px;
    order: -3;
    height: 100%;
    box-sizing: border-box;
}

@media (hover: none) {
    .tategaki .sentence rt {
        transform: translate(-7px, 1px);
        font-size: 0.5em;
        letter-spacing: 0.1em;
    }
}
/* iOS override must follow the mobile rule above to win source order */
@supports (-webkit-touch-callout: none) {
    .tategaki .sentence rt {
        font-size: 0.45em;
        margin-block: -0.5em;
        transform: translate(-0.15em, 0.07em);
    }
    @media (min-width: 768px) {
        .tategaki .sentence rt {
            transform: translate(0.35em, 0.07em);
        }
    }
}

/* Definition — placed right after audio buttons in R→L flow */
.tategaki .answer > .def-section {
    box-sizing: border-box;
    margin: 0 0 0 16px;
    order: -2;
    height: 100%;
    line-height: 1.7;
}

@media (hover: none) {
    .tategaki .def-section {
        text-align: start;
    }
}

.tategaki .def-toggle-label {
    writing-mode: vertical-rl;
    padding: 14px 3px;
}

.tategaki .def-toggle-label::after {
    transform: rotate(90deg);
}

.tategaki .def-toggle-input:checked + .def-toggle-label::after {
    transform: rotate(180deg);
}

.tategaki .answer > .def-section > .def.text-play {
    height: 100%;
}

.tategaki .answer > .def-section:has(.def[data-def-show="toggle"]) > .def[data-def-show="inline"].text-play {
    margin-left: 6px;
}

.tategaki .def[data-def-show="toggle"] {
    margin-top: 0;
    margin-right: 6px;
}

/* Notes — follows definitions in tategaki R→L flow */
.tategaki .notes-section {
    margin: 0 0 0 16px;
    margin-top: 0;
    height: 100%;
}

.tategaki .notes-section .notes {
    line-height: 1.7;
}

/* Details section — tategaki */
.tategaki .details-section {
    margin: 0 0 0 16px;
    margin-top: 0;
    height: 100%;
}

.tategaki .details-toggle {
    writing-mode: vertical-rl;
    padding: 14px 3px;
}

.tategaki .details-toggle::after {
    transform: rotate(90deg);
}

.tategaki .details-input:checked + .details-toggle::after {
    transform: rotate(180deg);
}

.tategaki .details-wrap {
    margin-top: 0;
    margin-right: 6px;
}

.tategaki .details-inner {
    min-width: 0;
    flex-direction: row;
    flex-wrap: wrap;
    height: 100%;
}

/* Tategaki details: each element gets its own column */
.tategaki .details-inner .target-word,
.tategaki .details-inner .pitch-graph,
.tategaki .details-inner .word-pitch-group,
.tategaki .details-inner .image-wrap,
.tategaki .details-inner .sentence,
.tategaki .details-inner .notes-section,
.tategaki .details-inner .def-section,
.tategaki .details-inner > .def {
    margin: 0;
    height: 100%;
}

/* word-pitch-group needs horizontal-tb when moved to details (loses it from .word-column > *);
   auto height so word and pitch graph stay grouped tightly */
.tategaki .details-inner .word-pitch-group {
    writing-mode: horizontal-tb;
    height: auto;
}

/* Tategaki details: word-column wrapper groups word + image like the normal word-column */
.tategaki .details-inner .details-word-column {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    align-content: flex-end;
    justify-content: space-between;
    height: 100%;
    gap: 18px;
}

.tategaki .details-inner .details-word-column > * {
    writing-mode: horizontal-tb;
    height: auto;
    margin: 0;
}

.tategaki .details-inner .details-word-column .word-pitch-group {
    max-width: 391px;
}

@media (hover: none) {
    .tategaki .details-inner .details-word-column .word-pitch-group {
        max-width: 100%;
    }
    .tategaki .details-inner .details-word-column .image-wrap {
        width: clamp(249px, 80vw, 391px);
    }
}

/* Divider */
html:not(.tategaki) .divider {
    display: none;
}

html:not(.tategaki) .back:not(:has(.front-content [data-side="front"]))
    .answer:has(> .sentence:not([data-show="off"]):not(:empty)):has(.def[data-def-show="inline"], .def[data-def-show="toggle"]) .divider {
    display: block;
}

html:not(.tategaki) .back:has(.front-content [data-side="front"])
    .answer:has(.def[data-def-show="inline"], .def[data-def-show="toggle"]) .divider,
html:not(.tategaki) .back:has(.front-content [data-side="front"])
    .answer:has(
        .target-word:not([data-show="off"]):not(:empty),
        .pitch-graph:not([data-state="empty"]),
        .sentence:not([data-show="off"]):not(:empty),
        .image-wrap:not([data-show="off"])
    ) .divider {
    display: block;
    order: -2;
}

.tategaki .divider {
    width: 1px;
    height: 100%;
    background: linear-gradient(180deg, transparent, var(--divider-color) 25%, var(--divider-color) 75%, transparent);
    margin: 0 0 0 24px;
    order: -4;
}

.tategaki .back:not(:has(.front-content [data-side="front"])):not(:has(.audio-row-bottom[data-zone="front"])) .divider {
    display: none;
}

html:not(.tategaki) .back:has(.front-content [data-side="front"]) .answer::before {
    content: '';
    display: block;
    height: 1px;
    margin: 0;
    background: linear-gradient(90deg, transparent, var(--answer-divider-color) 25%, var(--answer-divider-color) 75%, transparent);
    order: -2;
}

/* Audio-only front: move audio-row-bottom right of divider (front section) */
.tategaki .audio-row-bottom[data-zone="front"] {
    order: -5;
}

/* Children start hidden, .ri triggers staggered reveal (right-to-left) */
.tategaki .answer > [style*="--d"],
.tategaki .word-column [style*="--d"] {
    opacity: 0;
}

.tategaki .ri {
    animation: tategakiReveal 280ms var(--spring) both;
    animation-delay: calc(var(--d, 0) * 0.5ms);
}

/* Tategaki audio buttons: stagger in like front-side .fi */
.tategaki .audio-row-bottom.ri          { animation: none; opacity: 1; }
.tategaki .audio-row-bottom .audio-item {
    opacity: 0;
    animation: tategakiReveal 280ms var(--spring) both;
}
.tategaki .audio-row-bottom .audio-item[data-audio="word"]     { animation-delay: 0ms; }
.tategaki .audio-row-bottom .audio-item[data-audio="sentence"] { animation-delay: 35ms; }
.tategaki .audio-row-bottom .audio-item[data-audio="def"]      { animation-delay: 70ms; }

/* Front .fi — slide in from left like back-side elements */
.tategaki .fi {
    animation: tategakiReveal 0.5s var(--spring) both;
    animation-delay: calc(var(--d, 0) * 1ms);
}

/* Settle animations irrelevant — front audio row hidden on tategaki back */
.tategaki .back .audio-row .audio-item,
.tategaki .back .audio-row .audio-item .replay-button svg,
.tategaki .back .audio-row .audio-item .replay-button img,
.tategaki .back .audio-row .audio-label,
.tategaki .back .audio-row .audio-item.bi {
    animation: none;
}

/* Center ASCII hyphens vertically in CJK text */
.hc {
    position: relative;
    top: -0.1em;
}

.tategaki .hc {
    top: 0;
    left: 0.15em;
}

@media (hover: none) {
    .tategaki .hc {
        left: 0.21em;
    }
}

/* Full-width digits — helper for tategaki JS */
.tategaki .hor {
    writing-mode: horizontal-tb;
    display: inline;
}

/* AnkiDroid: disable all back-side animations (WebView performance) */
.android .answer > [style*="--d"],
.android .word-column [style*="--d"] {
    opacity: 1;
}

.android .ri {
    animation: none;
}

.android .back .audio-item.bi {
    animation: none;
}

.android .back .audio-row {
    animation: none;
}

/* AnkiDroid: disable tategaki animations */
.android.tategaki .card-inner:has(> .back) {
    animation: none;
}

.android.tategaki .answer > [style*="--d"],
.android.tategaki .word-column [style*="--d"] {
    opacity: 1;
}

.android.tategaki .ri {
    animation: none;
}

.android.tategaki .audio-row-bottom .audio-item {
    animation: none;
    opacity: 1;
}

/* AnkiDroid: plain background, opaque card, no sheen */
.android,
.android .card {
    background: var(--bg) !important;
}

.android .card-inner {
    background: var(--bg-card);
    border: none;
    box-shadow: none;
}

.android .card-inner::after {
    display: none;
}

/* Fix: WebKit miscalculates paint bounds for writing-mode:vertical-rl containers,
   visually clipping the audio buttons on their right edge. Promoting them to their
   own compositing layer lets them paint independently of the parent's broken bounds. */
.tategaki .audio-row-bottom {
    will-change: transform;
}

/* Dictionary lookup table (Notes field) — card-side overrides
   need !important to beat the inline styles set by addon/dev_migrate.py */
table.dict-table {
    border-collapse: collapse;
    margin: 0 auto !important;
}
table.dict-table td {
    border: 1px solid #ccc;
    padding: 2px 8px;
}


/* ═══ German word display (MvJ German) ═══
   der = blue, die = red, das = green, plural-only = orange.
   High specificity so the Japanese "no-accent" color reset doesn't win. */
:root {
    --de-m: #2f6fdf;
    --de-f: #d93a3a;
    --de-n: #1f9d55;
    --de-pl: #d97a1a;
}
:root[class*=night-mode] {
    --de-m: #6ea8ff;
    --de-f: #ff7a7a;
    --de-n: #5fd38d;
    --de-pl: #ffb35c;
}
/* Long compounds (Getränkeautomat…) must wrap instead of running off the card */
.target-word .de-word, #front-word .de-word, .de-word { white-space: normal; overflow-wrap: anywhere; hyphens: manual; }
.target-word.no-accent span.de-word.de-m, #front-word span.de-word.de-m, span.de-word.de-m { color: var(--de-m) !important; }
.target-word.no-accent span.de-word.de-f, #front-word span.de-word.de-f, span.de-word.de-f { color: var(--de-f) !important; }
.target-word.no-accent span.de-word.de-n, #front-word span.de-word.de-n, span.de-word.de-n { color: var(--de-n) !important; }
.target-word.no-accent span.de-word.de-pl, #front-word span.de-word.de-pl, span.de-word.de-pl { color: var(--de-pl) !important; }
span.de-word.de-long { font-size: min(0.72em, 7.5vw); }
span.de-word.de-xlong { font-size: min(0.55em, 5.5vw); }
span.de-grammar {
    display: block;
    font-size: 0.42em;
    font-weight: 400;
    letter-spacing: 0.02em;
    opacity: 0.7;
    margin-top: 0.25em;
    white-space: normal;
}

/* ── MvJ English: IPA under the word, Pronunciation section ── */
span.en-ipa {
    display: block;
    font-size: 0.42em;
    font-weight: 400;
    letter-spacing: 0.02em;
    opacity: 0.75;
    margin-top: 0.25em;
    white-space: normal;
    font-family: "Charis SIL", "Doulos SIL", "Gentium Plus", "Noto Sans", "Segoe UI", sans-serif;
}
span.en-ipa b.en-stress-syl { font-weight: 700; opacity: 1; color: var(--accent, inherit); }
.pron-section {
    width: 100%;
    max-width: 34em;
    margin: 0.6em auto 0;
    text-align: left;
    font-size: 0.8em;
    line-height: 1.45;
}
.pron .en-pron { display: flex; flex-direction: column; gap: 0.45em; }
.pron .en-stress { font-weight: 600; }
.pron .en-dots { letter-spacing: 0.15em; margin-right: 0.35em; }
.pron ul.en-tips { margin: 0; padding-left: 1.2em; }
.pron ul.en-tips li { margin: 0.15em 0; }
.pron ul.en-tips li::marker { content: "⚠ "; }
.pron .en-pair { display: flex; flex-wrap: wrap; align-items: center; gap: 0.2em 0.5em; }
.pron .en-pair-label { opacity: 0.7; font-size: 0.9em; width: 100%; }
.pron .en-pair-btn { display: inline-flex; width: 1.6em; height: 1.6em; vertical-align: middle; }
.pron .en-pair-btn svg { width: 100%; height: 100%; }

/* Dojo card video (the Video field's clip, see front.html) */
.card-video {
    position: relative;
    width: 100%;
    max-width: 720px;
    margin: 0 auto 20px;
    border-radius: 10px;
    overflow: hidden;
    background: #000;
    box-shadow: var(--image-shadow);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
}
.card-video {
    aspect-ratio: 16 / 9;   /* until the clip's own size is known, so nothing below moves */
    max-height: 62vh;
}
.card-video video {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
    background: #000;
    opacity: 0;
    transition: opacity 0.12s;
}
.card-video.ready video { opacity: 1; }
.card-video:not(.ready) .card-video-replay { opacity: 0; }
.card-video-replay {
    position: absolute;
    right: 10px;
    bottom: 10px;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.55);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: opacity 0.2s;
}
.card-video-replay svg { width: 22px; height: 22px; fill: #fff; }
.card-video.playing .card-video-replay { opacity: 0; }
.card-video.blocked .card-video-replay {
    right: 50%; bottom: 50%; transform: translate(50%, 50%);
    width: 64px; height: 64px; opacity: 1;
}
